from pathlib import Path
import json
apps=[]
base='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NAME · Pocket Foundry</title><link rel="stylesheet" href="../style.css"><main><nav><a href="../index.html">← Pocket Foundry</a><span>CAT</span></nav><h1>NAME</h1><p>DESC</p><section>BODY</section><footer>Local processing · No account · No API keys</footer></main><script type="module">import * as core from '../core.js';const $=s=>document.querySelector(s);const show=v=>$('#out').textContent=typeof v==='string'?v:JSON.stringify(v,null,2);const safe=fn=>{try{fn();}catch(e){show('Error: '+e.message);}};CODE</script></html>'''
text='<label>Input<textarea id="input" spellcheck="false"></textarea></label>'
out='<output id="out" aria-live="polite"></output>'
def add(id,name,cat,desc,body,code):
 apps.append(dict(id=id,name=name,category=cat,description=desc))
 s=base
 for k,v in [('NAME',name),('CAT',cat),('DESC',desc),('BODY',body),('CODE',code)]:s=s.replace(k,v)
 Path('apps/'+id+'.html').write_text(s,encoding='utf-8')
add('json-studio','JSON Studio','Developer','Format and validate JSON.',text+'<button id="go">Format</button>'+out,"$('#go').onclick=()=>safe(()=>show(JSON.parse($('#input').value)));$('#input').value='{\"hello\":\"world\"}';$('#go').click();")
add('text-lab','Text Lab','Writing','Live Unicode character, word, line and byte counts.',text+out,"$('#input').oninput=()=>show(core.words($('#input').value));$('#input').oninput();")
add('slug-workshop','Slug Workshop','Developer','Create readable Unicode URL slugs, one per line.',text+out,r"$('#input').oninput=()=>show($('#input').value.split('\n').map(core.slug).join('\n'));")
add('base64-desk','Base64 Desk','Developer','Encode and decode UTF-8 text including Korean and emoji.',text+'<button id="encode">Encode</button><button id="decode">Decode</button>'+out,"$('#encode').onclick=()=>safe(()=>show(core.encode64($('#input').value)));$('#decode').onclick=()=>safe(()=>show(core.decode64($('#input').value)));")
add('url-desk','URL Desk','Developer','Inspect URL query parameters and encode URI components.',text+'<button id="go">Inspect</button><button id="encode">Encode</button><button id="decode">Decode</button>'+out,"$('#go').onclick=()=>safe(()=>{const u=new URL($('#input').value);show({protocol:u.protocol,host:u.host,path:u.pathname,query:[...u.searchParams],hash:u.hash});});$('#encode').onclick=()=>show(encodeURIComponent($('#input').value));$('#decode').onclick=()=>safe(()=>show(decodeURIComponent($('#input').value)));")
add('csv-lens','CSV Lens','Data','Parse quoted CSV into JSON using the first row as keys.',text+'<button id="go">Parse</button>'+out,"$('#go').onclick=()=>safe(()=>{const [h,...rows]=core.csv($('#input').value);if(!h||new Set(h).size!==h.length)throw Error('Use unique column headers');if(rows.some(r=>r.length!==h.length))throw Error('Row width differs from header');show(rows.map(r=>Object.fromEntries(h.map((k,i)=>[k,r[i]]))));});")
add('line-diff','Line Diff','Developer','Compare texts using a longest common subsequence line diff.','<label>Before<textarea id="a"></textarea></label><label>After<textarea id="b"></textarea></label><button id="go">Compare</button>'+out,"$('#go').onclick=()=>safe(()=>show(core.diff($('#a').value,$('#b').value)));")
add('contrast-meter','Contrast Meter','Design','Check relative luminance contrast of text and background.','<label>Text<input type="color" id="a" value="#ffffff"></label><label>Background<input type="color" id="b" value="#10131b"></label><section id="preview">Readable design starts here.</section>'+out,"const run=()=>{const a=$('#a').value,b=$('#b').value,r=core.contrast(a,b);$('#preview').style.color=a;$('#preview').style.background=b;show({ratio:r.toFixed(2)+':1',normalAA:r>=4.5,normalAAA:r>=7,largeAA:r>=3});};$('#a').oninput=$('#b').oninput=run;run();")
add('gradient-forge','Gradient Forge','Design','Create a CSS gradient with a live preview.','<label>Start<input type="color" id="a" value="#8b5cf6"></label><label>End<input type="color" id="b" value="#22d3ee"></label><label>Angle<input id="angle" type="range" min="0" max="360" value="135"></label><div id="preview" style="height:280px;border-radius:16px"></div>'+out,"const run=()=>{const s=`linear-gradient(${$('#angle').value}deg, ${$('#a').value}, ${$('#b').value})`;$('#preview').style.background=s;show('background: '+s+';');};for(const e of document.querySelectorAll('input'))e.oninput=run;run();")
add('palette-dice','Palette Dice','Design','Generate repeatable palettes from a numeric seed.','<label>Seed<input type="number" id="seed" value="42"></label><button id="go">Generate</button><div class="row" id="colors"></div>'+out,r"const run=()=>{const r=core.seeded(Number($('#seed').value));const colors=Array.from({length:5},()=>`hsl(${Math.floor(r()*360)} 70% ${35+Math.floor(r()*40)}%)`);$('#colors').replaceChildren(...colors.map(c=>{const e=document.createElement('div');e.className='swatch';e.style.background=c;e.textContent=c;return e;}));show(':root {\n'+colors.map((c,i)=>`  --color-${i+1}: ${c};`).join('\n')+'\n}');};$('#go').onclick=run;run();")
add('focus-clock','Focus Clock','Productivity','A deadline-based focus timer that survives sleeping tabs.','<label>Minutes<input type="number" id="minutes" min="1" max="180" value="25"></label><div class="big" id="clock" role="timer"></div><button id="start">Start / Resume</button><button id="pause">Pause</button><button id="reset">Reset</button>'+out,"let remaining=1500000,deadline=0,running=false;const draw=()=>{if(running){remaining=Math.max(0,deadline-Date.now());if(!remaining){running=false;show('Session complete');}}const s=Math.ceil(remaining/1000);$('#clock').textContent=String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');};$('#start').onclick=()=>{if(!running){deadline=Date.now()+remaining;running=true;}};$('#pause').onclick=()=>{draw();running=false;};$('#reset').onclick=()=>{running=false;remaining=Math.min(180,Math.max(1,Number($('#minutes').value)||25))*60000;draw();};setInterval(draw,200);draw();")
add('decision-dice','Decision Dice','Productivity','Choose a nonempty line with cryptographic randomness.',text+'<button id="go">Pick one</button>'+out,r"$('#go').onclick=()=>safe(()=>{const choices=$('#input').value.split('\n').map(s=>s.trim()).filter(Boolean);if(!choices.length)throw Error('Enter choices');const a=new Uint32Array(1),limit=Math.floor(4294967296/choices.length)*choices.length;do{crypto.getRandomValues(a);}while(a[0]>=limit);show(choices[a[0]%choices.length]);});")
add('ohm-lab','Ohm Lab','Electronics','Explore ideal resistor current and power.','<label>Voltage (V)<input id="v" type="number" value="5" step="any"></label><label>Resistance (Ω)<input id="r" type="number" value="1000" step="any"></label>'+out,"const run=()=>safe(()=>{const r=core.resistor(Number($('#v').value),Number($('#r').value));show({current_mA:r.current*1000,power_mW:r.power*1000,note:'Ideal resistor only. Real component tolerances and ratings are not modeled.'});});$('#v').oninput=$('#r').oninput=run;run();")
add('pwm-sketch','PWM Sketch','Electronics','Draw an ideal PWM signal and calculate average voltage.','<label>Duty (%)<input id="duty" type="range" min="0" max="100" value="50"></label><label>Supply (V)<input id="v" type="number" value="5" step="any"></label><canvas width="800" height="280"></canvas>'+out,"const c=$('canvas'),ctx=c.getContext('2d');const run=()=>{const d=Number($('#duty').value)/100,v=Number($('#v').value);ctx.clearRect(0,0,800,280);ctx.strokeStyle='#a9f575';ctx.lineWidth=3;ctx.beginPath();for(let x=0;x<800;x++){const y=x%160<160*d?45:230;x?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.stroke();show({duty_percent:d*100,average_voltage:v*d,note:'Ideal switching waveform; not a motor simulation.'});};$('#duty').oninput=$('#v').oninput=run;run();")
add('life-garden','Life Garden','Simulation','Paint cells in Conway’s Game of Life on a wrapping grid.','<button id="toggle">Run / Pause</button><button id="step">Step</button><button id="random">Randomize</button><button id="clear">Clear</button><canvas width="640" height="480"></canvas>'+out,"const c=$('canvas'),ctx=c.getContext('2d'),w=40,h=30;let cells=Array(w*h).fill(0),running=false,g=0;const draw=()=>{ctx.fillStyle='#101624';ctx.fillRect(0,0,640,480);cells.forEach((v,i)=>{if(v){ctx.fillStyle='#a9f575';ctx.fillRect(i%w*16+1,Math.floor(i/w)*16+1,14,14);}});show('Generation '+g+' · Live cells '+cells.reduce((a,b)=>a+b,0));};const step=()=>{cells=core.life(cells,w,h);g++;draw();};$('#toggle').onclick=()=>running=!running;$('#step').onclick=step;$('#clear').onclick=()=>{cells.fill(0);g=0;draw();};$('#random').onclick=()=>{cells=cells.map(()=>Math.random()<.25?1:0);g=0;draw();};c.onpointerdown=e=>{const r=c.getBoundingClientRect(),x=Math.floor((e.clientX-r.left)/r.width*w),y=Math.floor((e.clientY-r.top)/r.height*h);if(x>=0&&x<w&&y>=0&&y<h){cells[y*w+x]^=1;draw();}};setInterval(()=>{if(running)step();},120);$('#random').click();")
add('orbit-ink','Orbit Ink','Art','Seeded generative orbital art with PNG export.','<label>Seed<input id="seed" type="number" value="17"></label><button id="go">Draw</button><button id="save">Save PNG</button><canvas width="800" height="800"></canvas>',"const c=$('canvas'),ctx=c.getContext('2d');const draw=()=>{const r=core.seeded(Number($('#seed').value));ctx.fillStyle='#10131b';ctx.fillRect(0,0,800,800);const a=2+Math.floor(r()*8),b=3+Math.floor(r()*10),phase=r()*Math.PI;ctx.lineWidth=.65;for(let j=0;j<10;j++){ctx.strokeStyle=`hsla(${140+j*19},85%,70%,.45)`;ctx.beginPath();for(let i=0;i<=4000;i++){const t=i/4000*Math.PI*2,x=400+Math.sin(a*t+phase+j*.02)*(330-j*12),y=400+Math.cos(b*t)*(330-j*12);i?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.stroke();}};$('#go').onclick=draw;$('#save').onclick=()=>{const a=document.createElement('a');a.download='orbit-ink.png';a.href=c.toDataURL();a.click();};draw();")
add('reaction-sprint','Reaction Sprint','Game','Measure reaction time after an unpredictable cue.','<button id="pad" style="width:100%;height:260px;font-size:30px">Start round</button>'+out,"let state='idle',timer,start;$('#pad').onclick=()=>{if(state==='waiting'){clearTimeout(timer);state='idle';$('#pad').textContent='Too early — try again';$('#pad').style.background='';}else if(state==='ready'){const ms=Math.round(performance.now()-start);state='idle';$('#pad').textContent=ms+' ms · Play again';show('Includes display and device latency');$('#pad').style.background='';}else{state='waiting';$('#pad').textContent='Wait for green…';$('#pad').style.background='#63708a';timer=setTimeout(()=>{state='ready';start=performance.now();$('#pad').style.background='#a9f575';$('#pad').textContent='NOW!';},1000+Math.random()*3000);}};")
add('typing-track','Typing Track','Game','Practice typing with elapsed-time speed and positional accuracy.','<p id="target"></p>'+text+'<button id="reset">Reset</button>'+out,"const target='Small tools make room for big ideas. Build something useful and keep learning.';$('#target').textContent=target;let start=0;$('#input').oninput=()=>{if(!start)start=performance.now();const s=$('#input').value,minutes=Math.max((performance.now()-start)/60000,1/60000);let correct=0;for(let i=0;i<s.length;i++)if(s[i]===target[i])correct++;show({words_per_minute:Math.round(s.length/5/minutes),accuracy:s.length?(100*correct/s.length).toFixed(1)+'%':'100%',complete:s===target});if(s===target)$('#input').disabled=true;};$('#reset').onclick=()=>{start=0;$('#input').disabled=false;$('#input').value='';show('Type to begin');};$('#reset').click();")
add('unix-clock','Unix Clock','Developer','Convert Unix seconds to an ISO date and back.','<label>Unix seconds<input id="seconds" type="number" value="0"></label><button id="decode">To date</button><label>ISO date<input id="date" value="2026-01-01T00:00:00Z"></label><button id="encode">To seconds</button>'+out,"$('#decode').onclick=()=>safe(()=>show(new Date(Number($('#seconds').value)*1000).toISOString()));$('#encode').onclick=()=>safe(()=>{const n=Date.parse($('#date').value);if(!Number.isFinite(n))throw Error('Invalid date');show(Math.floor(n/1000));});")
add('hash-desk','Hash Desk','Developer','Calculate a SHA-256 digest of UTF-8 text locally.',text+'<button id="go">SHA-256</button>'+out,"$('#go').onclick=async()=>{try{const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode($('#input').value));show([...new Uint8Array(b)].map(v=>v.toString(16).padStart(2,'0')).join(''));}catch(e){show(e.message);}};")
Path('catalog.json').write_text(json.dumps(apps,indent=2),encoding='utf-8')
Path('index.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pocket Foundry — Small tools. Big possibilities.</title><link rel="stylesheet" href="style.css"><main><nav><strong>◈ POCKET FOUNDRY</strong><span>OPEN SOURCE / LOCAL FIRST</span></nav><p class="eyebrow">A SMALL INTERNET TOOLBOX</p><h1>Small tools.<br>Big possibilities.</h1><p>Twenty experiments for your browser. No installs, accounts, API keys or tracking.</p><label>Search the collection<input id="search" type="search" placeholder="Try design, JSON, game…"></label><p id="count" aria-live="polite"></p><div class="grid" id="catalog"></div><footer>MIT licensed. All input processing stays in this browser.</footer></main><script type="module">const data=await(await fetch('./catalog.json')).json();const render=()=>{const q=document.querySelector('#search').value.toLowerCase();const items=data.filter(a=>(a.name+' '+a.description+' '+a.category).toLowerCase().includes(q));document.querySelector('#count').textContent=items.length+' tools ready';document.querySelector('#catalog').replaceChildren(...items.map(a=>{const link=document.createElement('a');link.className='card';link.href='apps/'+a.id+'.html';const tag=document.createElement('span');tag.textContent=a.category;const title=document.createElement('h2');title.textContent=a.name;const p=document.createElement('p');p.textContent=a.description;link.append(tag,title,p);return link;}));};document.querySelector('#search').oninput=render;render();</script></html>''',encoding='utf-8')
print('Created',len(apps),'apps')
